// Six invented, unbranded aircraft built procedurally from parts (control surfaces, flaps, spoilers, retractable gear, propeller,
// main and tail rotors move; on a crash the airframe breaks into these parts): 云雀 Lark L-1 trainer (high wing, 11 m span),
// 白鹭 Egret E-2 floatplane, 雨燕 Swift S-6 business jet (T-tail, rear engines), 海燕 Petrel P-200 twin narrow-body airliner
// (A320 / 737 class: 37.6 m long, 35.8 m span, 64 t), 蜻蜓 Dragonfly H-3 light helicopter (10.7 m rotor), 蜂鸟 Hummingbird D-1
// camera drone (quadcopter, first-person view).
// Flight model: 6-DOF rigid body at 240 Hz; fixed wing: lift curve with stall and post-stall, drag polar, flaps, ground effect,
// prop (power-limited, slipstream) or turbofans (spool lag, lapse, reversers), stability and control derivatives, rate-limited
// surfaces; helicopter: blade-element thrust with momentum / vortex-ring inflow, translational lift, ground effect, flapping,
// hub moments, torque, rotor speed with a governor and autorotation, tail rotor; drone: four-motor thrust / torque with lag. Gear legs (springs, rolling / braking / cornering
// friction), skids, floats (buoyancy, planing drag), airframe hard points. Assist levels 0 Direct / 1 Normal (fly-by-wire style)
// / 2 Easy. Wind from window.SGWx.
// Start places: the real runways of the map (SGR.base.runways, lined up on the threshold), heliports / open spots (own pads),
// water (floatplane), the air above the view. Tray: a 飞行 Flying section at the end of the drive pane (.tray-pane[data-cat="f1"]).
// Collisions: terrain, water (ditching / float landing), real buildings (own prism index per tile), road / rail decks (SGR.lines E),
// landmark and site models (own 3 m x 2 m voxel columns from their triangles, built near the aircraft, pooled), own helipads.
// Damage: gear (sink rate), airframe parts (impacts, scraping), over-stress, over-speed; crashes explode (window.SGFX: pooled
// particles: explosion / fire / smoke / sparks / splash, scorch decals) and the parts fly off and burn. R respawns.
// Sound through window.SGAudio.vehicle('fly', 'prop' | 'jet' | 'heli', p) and SGAudio.fx(...) (guarded).
// Optional: AI helicopters (news / tour / police style) circling landmarks.
// Only one vehicle mode: entering exits window.SGF1 (drive); if SGF1 turns on while flying, flying exits and hands over the saved view.
