/* ================= flight dynamics (pure JS: no THREE, testable in node) =================
   World frame ENU: x east, y north, z up (metres; the app's world x, y and height). Body frame FRD: x forward, y right, z down.
   A.q = quaternion body -> world, A.M = the same as a row-major 3x3 matrix, A.w = body rates [p roll right, q nose up, r nose right].
   Fixed wing: lift curve with a soft stall and a post-stall flat-plate branch, drag polar, flaps (CL, CLmax, CD, Cm), gear and
   spoiler drag, stability / control derivatives (per rad), prop (power-limited, slipstream over the tail) or turbofan (spool lag,
   thrust lapse, reversers), ground effect. Helicopter: blade-element thrust with momentum / empirical inflow (translational lift,
   vortex-ring, ground effect), flapping (cyclic, blow-back, rate lag), hub moments, torque and rotor speed (governor, autorotation),
   tail rotor, fuselage / fin / stabiliser drag. Contacts: sprung gear legs with rolling / braking / cornering friction, skids,
   floats (buoyancy + planing drag), airframe hard points; they report touchdown sink rates and impacts to the damage model. */
const G0 = 9.81, D2R = Math.PI/180, KT = 1.943844, FT = 3.28084;
const clampF = (v, a, b) => v < a ? a : v > b ? b : v;
