const sig = x => 1/(1 + Math.exp(-x));
// ---- quaternion / matrix helpers (arrays; no allocation)
function qToM(q, M){
  const w = q[0], x = q[1], y = q[2], z = q[3];
  M[0] = 1 - 2*(y*y + z*z); M[1] = 2*(x*y - w*z); M[2] = 2*(x*z + w*y);
  M[3] = 2*(x*y + w*z); M[4] = 1 - 2*(x*x + z*z); M[5] = 2*(y*z - w*x);
  M[6] = 2*(x*z - w*y); M[7] = 2*(y*z + w*x); M[8] = 1 - 2*(x*x + y*y);
  return M;
}
function mToQ(M, q){
  const t = M[0] + M[4] + M[8];
  if (t > 0){ const s = Math.sqrt(t + 1)*2; q[0] = 0.25*s; q[1] = (M[7] - M[5])/s; q[2] = (M[2] - M[6])/s; q[3] = (M[3] - M[1])/s; }
  else if (M[0] > M[4] && M[0] > M[8]){ const s = Math.sqrt(1 + M[0] - M[4] - M[8])*2; q[0] = (M[7] - M[5])/s; q[1] = 0.25*s; q[2] = (M[1] + M[3])/s; q[3] = (M[2] + M[6])/s; }
  else if (M[4] > M[8]){ const s = Math.sqrt(1 + M[4] - M[0] - M[8])*2; q[0] = (M[2] - M[6])/s; q[1] = (M[1] + M[3])/s; q[2] = 0.25*s; q[3] = (M[5] + M[7])/s; }
  else { const s = Math.sqrt(1 + M[8] - M[0] - M[4])*2; q[0] = (M[3] - M[1])/s; q[1] = (M[2] + M[6])/s; q[2] = (M[5] + M[7])/s; q[3] = 0.25*s; }
  return q;
}
const mv = (M, x, y, z, o) => { o[0] = M[0]*x + M[1]*y + M[2]*z; o[1] = M[3]*x + M[4]*y + M[5]*z; o[2] = M[6]*x + M[7]*y + M[8]*z; return o; };
const mtv = (M, x, y, z, o) => { o[0] = M[0]*x + M[3]*y + M[6]*z; o[1] = M[1]*x + M[4]*y + M[7]*z; o[2] = M[2]*x + M[5]*y + M[8]*z; return o; };
// heading psi (compass, 0 = north, clockwise), pitch th (nose up), bank ph (right wing down) -> body->ENU quaternion
function qFromEuler(psi, th, ph, q){
  const cs = Math.cos(psi), ss = Math.sin(psi), ct = Math.cos(th), st = Math.sin(th), cp = Math.cos(ph), sp = Math.sin(ph), M = qFromEuler.M;
  // R_ned = Rz(psi) Ry(th) Rx(ph); ENU rows = [NED row 1 (east), NED row 0 (north), -NED row 2 (up)]
  M[0] = ct*ss; M[1] = sp*st*ss + cp*cs; M[2] = cp*st*ss - sp*cs;
  M[3] = ct*cs; M[4] = sp*st*cs - cp*ss; M[5] = cp*st*cs + sp*ss;
  M[6] = st;    M[7] = -sp*ct;           M[8] = -cp*ct;
  return mToQ(M, q);
}
qFromEuler.M = new Float64Array(9);
function eulerOf(M, o){ o.th = Math.asin(clampF(M[6], -1, 1)); o.ph = Math.atan2(-M[7], -M[8]); o.psi = Math.atan2(M[0], M[3]); return o; }

