    const down = z + r - (zd - 2.4), side = hw + r - d; let dep, nx = 0, ny = 0, nz = 0;
    if (down < side){ dep = down; nz = -1; } else { dep = side; nx = -LSEG.dy[i]*LSEG.s[i]; ny = LSEG.dx[i]*LSEG.s[i]; }
