    const j2 = (j + 1) % m, a = R[i][j], b = R[i + 1][j], c = R[i + 1][j2], d = R[i][j2];
    // orientation: outward
    const ux = b[0] - a[0], uy = b[1] - a[1], uz = b[2] - a[2], vx = d[0] - a[0], vy = d[1] - a[1], vz = d[2] - a[2], fx = uy*vz - uz*vy, fy = uz*vx - ux*vz, fz = ux*vy - uy*vx;
    const na = N[i][j], flip = fx*na[0] + fy*na[1] + fz*na[2] < 0;
