  const c = Math.cos(a), s = Math.sin(a), e = 2/q.e, z = Math.sign(c)*Math.pow(Math.abs(c), e)*(q.w + (off || 0)), y = q.cy + Math.sign(s)*Math.pow(Math.abs(s), e)*((s >= 0 ? q.ht : q.hb) + (off || 0));
