  { const scr = M.P('scr', 'body'); for (let i = 0; i < 4; i++) gBox(scr, 6.07, -0.02, -0.5 + i*0.33, 0.005, 0.1, 0.12, i % 2 ? hex('#2f6f9f') : hex('#3b7a52')); }
  for (const s2 of [-1, 1]){ gCyl(inr, [6.9, 0.35, 0.3*s2], [6.15, 0.82, 0.35*s2], 0.03, 5, C_INT); gCyl(inr, [6.55, 0.15, 0.8*s2], [6.0, 0.8, 0.62*s2], 0.035, 5, C_INT); } gCyl(inr, [6.95, 0.4, 0], [6.1, 0.85, 0], 0.025, 5, C_INT);
