  for (const s of [-1, 1]){ gBox(inr, 14.6, -0.7, 0.55*s, 0.32, 0.07, 0.27, C_SEAT); gBox(inr, 14.25, -0.15, 0.55*s, 0.07, 0.5, 0.27, C_SEAT); gBox(inr, 15.25, -0.42, 0.88*s, 0.12, 0.04, 0.04, C_DARK); }
  for (const s2 of [-1, 1]){ for (const x of [16.33, 15.83, 15.26, 14.78]) gCyl(inr, [x, fsPt(fs(x), s2 > 0 ? 0.48 : Math.PI - 0.48, -0.06)[1], fsPt(fs(x), s2 > 0 ? 0.48 : Math.PI - 0.48, -0.06)[2]], [x - 0.02, fsPt(fs(x), s2 > 0 ? 1.05 : Math.PI - 1.05, -0.06)[1], fsPt(fs(x), s2 > 0 ? 1.05 : Math.PI - 1.05, -0.06)[2]], 0.04, 5, C_INT); }
  gCyl(inr, [16.6, fsPt(fs(16.6), Math.PI/2, -0.05)[1] - 0.25, 0], [16.3, fsPt(fs(16.3), Math.PI/2, -0.05)[1], 0], 0.045, 5, C_INT);
