/* ======== Hummingbird camera drone (quadcopter, 0.95 m across the props) ======== */
function buildDrone(liv){
  const M = newModel(), A = hex(liv.a), Bc = hex(liv.b), Cc = hex(liv.c), body = M.P('body');
  const fs = fusSampler([[0.2, 0.0, 0.002, 0.002, 0.002, 2], [0.17, 0.0, 0.08, 0.05, 0.05, 2.6], [0.05, 0.01, 0.1, 0.06, 0.05, 3.2], [-0.12, 0.01, 0.09, 0.055, 0.045, 3], [-0.2, 0.01, 0.002, 0.002, 0.002, 2]]);
  gFus(body, fs, -0.2, 0.2, 10, 16, p => p[1] > 0.04 ? Bc : A);
  gLathe(body, [[0.02, 0.002], [0.02, 0.035], [-0.02, 0.035], [-0.02, 0.002]], 0.075, 0, 10, Cc, false, false);
  for (const [sx, sz, k] of [[1, -1, 0], [1, 1, 1], [-1, -1, 2], [-1, 1, 3]]){
    const x = 0.34*sx, z = 0.34*sz;
    gCyl(body, [0.05*sx, 0.0, 0.05*sz], [x, 0.01, z], 0.016, 6, A);
    gCyl(body, [x, -0.02, z], [x, 0.04, z], 0.028, 10, C_DARK, true);
    const pr = M.P('prop' + k, 'body', [x, 0.05, z], [0, 1, 0]);
    for (let b = 0; b < 2; b++){ const a = b*Math.PI + k, c = Math.cos(a), sn = Math.sin(a), w = 0.022;
      gPoly(pr, [[x + c*0.02 - sn*w, 0.05, z + sn*0.02 + c*w], [x + c*0.19 - sn*w*0.6, 0.052, z + sn*0.19 + c*w*0.6], [x + c*0.19 + sn*w*0.6, 0.048, z + sn*0.19 - c*w*0.6], [x + c*0.02 + sn*w, 0.05, z + sn*0.02 - c*w]], k < 2 ? hex('#e8e6e0') : C_PROP, [0, 1, 0]);
      gPoly(pr, [[x + c*0.02 - sn*w, 0.05, z + sn*0.02 + c*w], [x + c*0.02 + sn*w, 0.05, z + sn*0.02 - c*w], [x + c*0.19 + sn*w*0.6, 0.048, z + sn*0.19 - c*w*0.6], [x + c*0.19 - sn*w*0.6, 0.052, z + sn*0.19 + c*w*0.6]], k < 2 ? hex('#e8e6e0') : C_PROP, [0, -1, 0]); }
    M['disc' + k] = {p:[x, 0.051, z], r:0.19, axis:'y'};
    M.lights.push({k:sx > 0 ? (sz < 0 ? 'navR' : 'navG') : 'strobe', p:[x, -0.025, z]});
  }
  // landing legs, camera gimbal
  const lg = M.P('legs', 'body'); for (const sz of [-1, 1]){ gCyl(lg, [0.16, -0.21, 0.2*sz], [-0.16, -0.21, 0.2*sz], 0.008, 5, C_DARK); for (const sx of [1, -1]) gCyl(lg, [0.12*sx, -0.21, 0.2*sz], [0.07*sx, -0.04, 0.07*sz], 0.007, 5, C_DARK); }
  gCyl(body, [0.12, -0.04, 0], [0.12, -0.07, 0], 0.012, 6, C_DARK); gLathe(body, [[0.17, 0.002], [0.16, 0.035], [0.12, 0.045], [0.08, 0.035], [0.07, 0.002]], -0.1, 0, 10, hex('#2c3036'), false, false);
  gLathe(body, [[0.172, 0.002], [0.171, 0.022], [0.168, 0.002]], -0.1, 0, 10, hex('#0d1a2a'), false, false);
  M.lights.push({k:'beacon', p:[-0.12, 0.07, 0]});
  M.seat = [0.18, -0.1, 0];
  return M;
}
