    // aileron: positive da = right aileron up (trailing edge up), left down; hinge axes point outboard-ish (from root to tip)
    hingeSet(pr.ailR, -S.da*1.0); hingeSet(pr.ailL, -S.da*1.0);
    hingeSet(pr.elevR, S.de); hingeSet(pr.elevL, -S.de);
