  setTF(q.engL, 'engL', heli ? '旋翼 NR · 功率 PWR' : drone ? '电机 MOTORS' : P.eng.t === 'jet' ? '发动机 N1' : '发动机 RPM');
  setTF(q.eng, 'eng', !A.eng.on && !heli ? 'OFF' : drone ? Math.round(A.eng.pw*100) + '%' : heli ? `${Math.round(A.rot.Om/P.Om*100)}% · ${Math.round(A.rot.Pe/1000)} kW` : P.eng.t === 'jet' ? A.eng.n1s.map(n => Math.round(n*100)).join(' / ') + (A.srf.rev > 0.5 ? ' REV' : '') : Math.round(A.eng.rpm*2700) + '');
