  const gs = P.gearUp ? (A.srf.gear > 0.99 ? 'd' : A.srf.gear < 0.01 ? '' : 't') : 'd';
  const gk = gs + ['gearN', 'gearL', 'gearR'].map(k => A.gearGone[k] ? 1 : 0).join('');
