  const dm = Math.min(1, Math.max(...Object.values(A.dmg).map(v => v || 0))); setTF(q.dmg, 'dmg', Math.round(dm*100) + '%'); if (HUDF.last.dmw !== Math.round(dm*100)){ HUDF.last.dmw = Math.round(dm*100); q.dmgB.style.width = HUDF.last.dmw + '%'; }
