  c.fillStyle = '#fff'; c.font = `600 10px ${F}`; c.fillText((vs >= 0 ? '+' : '') + Math.round(vs/10)*10, vx + 13, cy + (vs >= 0 ? 12 : -10)); c.font = `500 8.5px ${F}`; c.fillStyle = '#9fb0b8'; c.fillText('FPM', vx + 13, 18); c.fillText(`${A.v[2].toFixed(1)} m/s`, vx + 13, 205);
