  c.strokeStyle = '#cfd8dc'; c.fillStyle = '#cfd8dc'; c.font = `500 10px ${F}`; c.textAlign = 'center';
  for (let d = Math.floor((hd - 40)/5)*5; d <= hd + 40; d += 5){ const x = 220 + (d - hd)*2.6, dd = (d + 360) % 360; c.beginPath(); c.moveTo(x, hy - 10); c.lineTo(x, hy - (dd % 10 ? 6 : 3)); c.stroke(); if (dd % 30 === 0) c.fillText({0:'N', 90:'E', 180:'S', 270:'W'}[dd] || String(dd/10), x, hy + 8); }
  c.restore(); c.fillStyle = '#ffd23f'; c.font = `600 12px ${F}`; c.fillText(String(Math.round(hd) % 360).padStart(3, '0') + '°', 220, 244);
  c.beginPath(); c.moveTo(220, hy - 10); c.lineTo(215, hy - 16); c.lineTo(225, hy - 16); c.closePath(); c.fill();
