  OVF.hemi.color.copy(hemi.color); OVF.hemi.groundColor.copy(hemi.groundColor); OVF.hemi.intensity = hemi.intensity; OVF.sun.color.copy(sun.color); OVF.sun.intensity = sun.intensity*0.9;
  OVF.sun.position.copy(sun.position).sub(sun.target.position); OVF.sun.target.position.set(0, 0, 0); OVF.sun.target.updateMatrixWorld();
